// Preparar los controles de combobox
var formulario = theRoot.dataView();
var separador = formulario.control("SEP");
var subformulario = separador.form("sygemat_corralon_app/FPG_M_CND_ESP");

var combobox_1 = subformulario.control("DOC_TIP_1");
var combobox_2 = subformulario.control("DOC_TIP_2");
var combobox_3 = subformulario.control("DOC_TIP_3");
var combobox_4 = subformulario.control("DOC_TIP_4");
var combobox_5 = subformulario.control("DOC_TIP_5");
var combobox_6 = subformulario.control("DOC_TIP_6");
var combobox_7 = subformulario.control("DOC_TIP_7");
var combobox_8 = subformulario.control("DOC_TIP_8");
var combobox_9 = subformulario.control("DOC_TIP_9");

// Leer los valores de los combobox dejándolos en las variables locales
var codigo = combobox_1.itemData(combobox_1.currentIndex);
if (codigo) theRoot.setVar("DOC_TIP_1", codigo);
var codigo = combobox_2.itemData(combobox_2.currentIndex);
if (codigo) theRoot.setVar("DOC_TIP_2", codigo);
var codigo = combobox_3.itemData(combobox_3.currentIndex);
if (codigo) theRoot.setVar("DOC_TIP_3", codigo);
var codigo = combobox_4.itemData(combobox_4.currentIndex);
if (codigo) theRoot.setVar("DOC_TIP_4", codigo);
var codigo = combobox_5.itemData(combobox_5.currentIndex);
if (codigo) theRoot.setVar("DOC_TIP_5", codigo);
var codigo = combobox_6.itemData(combobox_6.currentIndex);
if (codigo) theRoot.setVar("DOC_TIP_6", codigo);
var codigo = combobox_7.itemData(combobox_7.currentIndex);
if (codigo) theRoot.setVar("DOC_TIP_7", codigo);
var codigo = combobox_8.itemData(combobox_8.currentIndex);
if (codigo) theRoot.setVar("DOC_TIP_8", codigo);
var codigo = combobox_9.itemData(combobox_9.currentIndex);
if (codigo) theRoot.setVar("DOC_TIP_9", codigo);

//Mostramos pestaña de condiciones especiales
var frm = theRoot.dataView();
var sep = theRoot.dataView().control("SEP");
var tab = sep.findForm("sygemat_corralon_app/FPG_M_CND_ESP");
var subForm = sep.form(tab).root();
var bucle = theRoot.varToInt("BUC");
var idVar = "POR_" + bucle;
var por  = subForm.varToInt(idVar);
var idVar = "DIA_" + bucle;
var dia = subForm.varToInt(idVar);

theRoot.setVar("POR", por);
theRoot.setVar("DIA", dia);

//Ocultamos pestaña de condiciones especiales
var frm = theRoot.dataView().mainForm();
var sep = frm.control("SEP");
var tab = sep.findForm("sygemat_corralon_app/FPG_M_CND_ESP");
if (tab > -1)
{ 
	sep.removeForm(tab);
}

//Mostramos pestaña de condiciones especiales
var frm = theRoot.dataView().mainForm();
var sep = frm.control("SEP");
var tab = sep.findForm("sygemat_corralon_app/FPG_M_CND_ESP");
if (tab == -1)
{ 
	sep.insertForm(0, "sygemat_corralon_app/FPG_M_CND_ESP", "Condiciones especiales", "");
}
